window.docContents[216].resolve({"/Literate-Programming/#literate-declaration-docstrings-as-text":{"contents":"By default, declaration docstrings render inside code boxes, visually grouped with the code.\nHowever, in some documents, the docstrings should be seen as part of the text.\nSetting docstrings_as_text causes them to render as prose text between code boxes instead, which is useful when they contain substantial prose or theorem names.\n\ndocstrings_as_text = true\n\n\nThis can be scoped per module prefix via [modules].\n\n","context":"Writing Documentation in Lean with Verso\u0009Literate Programming\u0009Configuration File Reference\u0009Declaration Docstrings","header":"8.3.8.1. Declaration Docstrings as Text","id":"/Literate-Programming/#literate-declaration-docstrings-as-text"}});